// ==================== SUPER MARIO-STYLE PLATFORMER ENGINE ====================
// "Super Jump Run": A side-scrolling platformer where kids solve Math & Reading
// questions (generated by the existing MathEngine, WORD_LEVELS, and RaceEngine)
// to jump, bonk [?] Mystery Blocks, collect coins & Super Mushrooms, leap over
// green Warp Pipes and critters, and reach the Castle Flagpole!

(function (root) {
  const TOTAL_CHECKPOINTS = 8;

  const WORLDS = [
    {
      id: '1-1',
      name: 'World 1-1 • Mushroom Meadow',
      skyTop: '#38bdf8',
      skyBottom: '#bae6fd',
      hillColor: '#22c55e',
      groundTop: '#4ade80',
      brickColor: '#b45309',
    },
    {
      id: '1-2',
      name: 'World 1-2 • Crystal Underground',
      skyTop: '#0f172a',
      skyBottom: '#1e1b4b',
      hillColor: '#312e81',
      groundTop: '#38bdf8',
      brickColor: '#1d4ed8',
    },
    {
      id: '1-3',
      name: 'World 1-3 • Sunset Athletic Sky',
      skyTop: '#7c2d12',
      skyBottom: '#fb923c',
      hillColor: '#ea580c',
      groundTop: '#fde047',
      brickColor: '#9a3412',
    },
  ];

  const OBSTACLE_TYPES = [
    { type: 'pipe', label: 'Green Warp Pipe', icon: '🟩' },
    { type: 'goomba', label: 'Grumpy Goom-Bug', icon: '👾' },
    { type: 'koopa', label: 'Spiky Shell Trooper', icon: '🐢' },
    { type: 'piranha', label: 'Chomping Pipe Plant', icon: '🌺' },
  ];

  function createRunState(leaderChar, worldIndex = 0) {
    const world = WORLDS[worldIndex % WORLDS.length];
    const obstacles = [];
    for (let i = 0; i < TOTAL_CHECKPOINTS; i++) {
      const obs = OBSTACLE_TYPES[i % OBSTACLE_TYPES.length];
      obstacles.push({
        index: i,
        ...obs,
        cleared: false,
      });
    }

    return {
      world,
      worldIndex: worldIndex % WORLDS.length,
      heroName: leaderChar ? leaderChar.name : 'Heartsping',
      heroSymbol: leaderChar ? leaderChar.symbol : '💖',
      heroAccent: leaderChar ? leaderChar.accent : '#ff6b9d',
      checkpoint: 0,
      totalCheckpoints: TOTAL_CHECKPOINTS,
      coins: 0,
      score: 0,
      streak: 0,
      powerUp: 'normal', // 'normal' | 'mushroom' | 'star'
      obstacles,
      finished: false,
    };
  }

  // Strictly delegates to existing RaceEngine / MathEngine / WORD_LEVELS generators
  function makeBlockQuestion(category, MathEngine, WORD_LEVELS, RaceEngine) {
    if (RaceEngine && typeof RaceEngine.makeQuestion === 'function') {
      const q = RaceEngine.makeQuestion(category || 'mix', MathEngine, WORD_LEVELS);
      return {
        ...q,
        badge: q.category === 'math' ? '🧱 [?] MATH BLOCK' : '🧱 [?] WORD BLOCK',
      };
    }
    throw new Error('RaceEngine is required to generate platformer questions');
  }

  function applyJumpResult(state, isCorrect, answerDurationSeconds = 3.0) {
    if (!state) return null;

    if (!isCorrect) {
      state.streak = 0;
      const lostPower = state.powerUp !== 'normal';
      state.powerUp = 'normal';
      return {
        correct: false,
        action: 'pipe-bump',
        bonusCoins: 0,
        bonusScore: 0,
        powerUpEarned: null,
        lostPower,
        callout: lostPower
          ? '💥 Bumped the pipe! Lost Super Power—try another [?] block!'
          : '💥 Bonk! That block was solid brick—tap the right [?] block to jump!',
      };
    }

    state.streak = (state.streak || 0) + 1;
    state.checkpoint = Math.min(state.totalCheckpoints, state.checkpoint + 1);
    if (state.obstacles[state.checkpoint - 1]) {
      state.obstacles[state.checkpoint - 1].cleared = true;
    }

    const isFast = answerDurationSeconds <= 3.5;
    let bonusCoins = isFast ? 3 : 1;
    let bonusScore = isFast ? 300 : 100;
    let powerUpEarned = null;
    let action = 'super-jump';
    let callout = `🪙 +${bonusCoins} Coin${bonusCoins > 1 ? 's' : ''}! Nice Jump! (+${bonusScore} PTS)`;

    if (state.streak >= 3) {
      state.powerUp = 'star';
      powerUpEarned = '🌟 SUPER STAR';
      bonusCoins = 5;
      bonusScore = 500;
      action = 'star-leap';
      callout = '🌟 SUPER STAR POWER! Invincible Sommersault! (+500 PTS)';
    } else if (state.streak === 2 || isFast) {
      if (state.powerUp === 'normal') {
        state.powerUp = 'mushroom';
        powerUpEarned = '🍄 SUPER MUSHROOM';
      }
      bonusScore = 300;
      callout = '🍄 SUPER JUMP! Bonked the [?] Block for +3 Coins! (+300 PTS)';
    }

    if (state.checkpoint >= state.totalCheckpoints) {
      state.finished = true;
      bonusScore += 1000;
      bonusCoins += 5;
      action = 'flagpole-win';
      callout = '🚩 TOP OF THE FLAGPOLE! +1000 BONUS PTS! 🏰';
    }

    state.coins += bonusCoins;
    state.score += bonusScore;

    return {
      correct: true,
      action,
      bonusCoins,
      bonusScore,
      powerUpEarned,
      checkpoint: state.checkpoint,
      finished: state.finished,
      callout,
    };
  }

  // Renders an interactive Super Mario-style side-scrolling SVG viewport
  function renderStageSvg(state, animState = 'idle') {
    if (!state) return '';
    const w = state.world || WORLDS[0];
    const cp = state.checkpoint;
    const total = state.totalCheckpoints;
    const scrollOffset = cp * 85;
    const currentObs = state.obstacles[Math.min(total - 1, cp)] || OBSTACLE_TYPES[0];

    // Hero coordinates and jump arc
    const isJumping = animState === 'super-jump' || animState === 'star-leap' || animState === 'flagpole-win';
    const isBumping = animState === 'pipe-bump';
    const heroY = isJumping ? 68 : 138;
    const heroX = animState === 'flagpole-win' ? 495 : isBumping ? 128 : 145;
    const heroScale = state.powerUp === 'mushroom' || state.powerUp === 'star' ? 1.18 : 1.0;

    // Parallax clouds & hills shifted by scrollOffset
    const cloud1X = 580 - ((scrollOffset * 0.4) % 620);
    const cloud2X = 580 - (((scrollOffset * 0.4) + 310) % 620);
    const hill1X = 560 - ((scrollOffset * 0.65) % 640);
    const hill2X = 560 - (((scrollOffset * 0.65) + 320) % 640);

    // Question block directly above hero
    const blockY = isJumping ? 30 : 42;
    const blockFill = isJumping ? '#fde047' : '#f59e0b';

    // Popping coin or power-up above the [?] block when jumping
    const popRewardSvg = isJumping
      ? `<g class="mario-block-pop">
           <circle cx="165" cy="16" r="12" fill="#fde047" stroke="#b45309" stroke-width="2.5"/>
           <text x="165" y="21" text-anchor="middle" font-size="13" font-weight="900" fill="#92400e">${
             state.powerUp === 'star' ? '🌟' : state.powerUp === 'mushroom' ? '🍄' : '🪙'
           }</text>
         </g>`
      : '';

    // Obstacle graphic at x=285
    let obstacleSvg = '';
    if (cp < total) {
      if (currentObs.type === 'pipe' || currentObs.type === 'piranha') {
        obstacleSvg = `<g class="mario-obstacle">
          ${
            currentObs.type === 'piranha'
              ? `<circle cx="305" cy="112" r="14" fill="#ef4444" stroke="#fff" stroke-width="2"/>
                 <circle cx="300" cy="108" r="2.5" fill="#fff"/>
                 <circle cx="311" cy="114" r="2.5" fill="#fff"/>`
              : ''
          }
          <rect x="282" y="132" width="46" height="46" fill="#22c55e" stroke="#14532d" stroke-width="3"/>
          <rect x="276" y="120" width="58" height="14" rx="3" fill="#4ade80" stroke="#14532d" stroke-width="3"/>
          <rect x="288" y="123" width="6" height="52" fill="#86efac" opacity="0.65"/>
        </g>`;
      } else {
        // Critter (Goomba / Koopa) with little feet
        obstacleSvg = `<g class="mario-obstacle">
          <ellipse cx="305" cy="160" rx="20" ry="16" fill="#b45309" stroke="#451a03" stroke-width="2.5"/>
          <circle cx="298" cy="156" r="3.5" fill="#fff"/>
          <circle cx="312" cy="156" r="3.5" fill="#fff"/>
          <ellipse cx="295" cy="174" rx="7" ry="4" fill="#1c1917"/>
          <ellipse cx="315" cy="174" rx="7" ry="4" fill="#1c1917"/>
          <text x="305" y="140" text-anchor="middle" font-size="14">${currentObs.icon}</text>
        </g>`;
      }
    }

    // Castle & Flagpole appear on the right (closer as cp approaches total)
    const castleBaseX = Math.max(460, 740 - cp * 38);
    const flagY = animState === 'flagpole-win' ? 62 : 118;

    return `<svg viewBox="0 0 640 220" class="mario-stage-svg" role="img" aria-label="${w.name} Checkpoint ${cp} of ${total}">
      <defs>
        <linearGradient id="m-sky" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="${w.skyTop}"/>
          <stop offset="100%" stop-color="${w.skyBottom}"/>
        </linearGradient>
        <pattern id="m-bricks" width="32" height="16" patternUnits="userSpaceOnUse">
          <rect width="32" height="16" fill="${w.brickColor}"/>
          <path d="M0 0 H32 M0 8 H32 M16 0 V8 M8 8 V16 M24 8 V16" stroke="#451a03" stroke-width="2"/>
        </pattern>
      </defs>

      <!-- Sky Backdrop -->
      <rect width="640" height="220" fill="url(#m-sky)"/>

      <!-- Parallax Clouds -->
      <g opacity="0.9" fill="#ffffff">
        <ellipse cx="${cloud1X}" cy="42" rx="34" ry="15"/>
        <ellipse cx="${cloud1X + 20}" cy="36" rx="24" ry="14"/>
        <ellipse cx="${cloud2X}" cy="54" rx="40" ry="16"/>
        <ellipse cx="${cloud2X - 22}" cy="48" rx="22" ry="12"/>
      </g>

      <!-- Parallax Super Mario Hills -->
      <path d="M${hill1X - 70} 178 Q${hill1X} 105 ${hill1X + 70} 178 Z" fill="${w.hillColor}" stroke="#14532d" stroke-width="2.5"/>
      <path d="M${hill2X - 55} 178 Q${hill2X} 125 ${hill2X + 55} 178 Z" fill="${w.hillColor}" opacity="0.85" stroke="#14532d" stroke-width="2"/>

      <!-- Overhead Brick & [?] Mystery Block Platform -->
      <g transform="translate(115, ${blockY})">
        <rect x="0" y="0" width="32" height="32" rx="4" fill="#b45309" stroke="#451a03" stroke-width="2.5"/>
        <rect x="34" y="0" width="36" height="32" rx="5" fill="${blockFill}" stroke="#78350f" stroke-width="3"/>
        <text x="52" y="23" text-anchor="middle" font-size="20" font-weight="900" fill="#78350f">?</text>
        <circle cx="39" cy="5" r="2" fill="#78350f"/>
        <circle cx="65" cy="5" r="2" fill="#78350f"/>
        <circle cx="39" cy="27" r="2" fill="#78350f"/>
        <circle cx="65" cy="27" r="2" fill="#78350f"/>
        <rect x="72" y="0" width="32" height="32" rx="4" fill="#b45309" stroke="#451a03" stroke-width="2.5"/>
      </g>
      ${popRewardSvg}

      <!-- Floating Coin Trail -->
      <g>
        <circle cx="235" cy="92" r="9" fill="#fde047" stroke="#ca8a04" stroke-width="2"/>
        <circle cx="262" cy="76" r="9" fill="#fde047" stroke="#ca8a04" stroke-width="2"/>
        <circle cx="290" cy="92" r="9" fill="#fde047" stroke="#ca8a04" stroke-width="2"/>
      </g>

      <!-- Active Pipe / Critter Obstacle -->
      ${obstacleSvg}

      <!-- Goal Flagpole & Star Castle -->
      <g transform="translate(${castleBaseX}, 0)">
        <!-- Flagpole -->
        <line x1="35" y1="36" x2="35" y2="178" stroke="#fef08a" stroke-width="5"/>
        <circle cx="35" cy="34" r="7" fill="#fde047" stroke="#ca8a04" stroke-width="2"/>
        <polygon points="35,${flagY} 5,${flagY + 12} 35,${flagY + 24}" fill="#ef4444" stroke="#fff" stroke-width="1.5"/>
        <rect x="25" y="166" width="20" height="12" fill="#78350f" stroke="#451a03" stroke-width="2"/>
        <!-- Brick Castle -->
        <rect x="70" y="98" width="84" height="80" rx="4" fill="#dc2626" stroke="#7f1d1d" stroke-width="3"/>
        <rect x="84" y="74" width="56" height="28" fill="#b91c1c" stroke="#7f1d1d" stroke-width="2.5"/>
        <!-- Castle Battlements -->
        <rect x="70" y="88" width="16" height="12" fill="#dc2626" stroke="#7f1d1d" stroke-width="2"/>
        <rect x="94" y="88" width="16" height="12" fill="#dc2626" stroke="#7f1d1d" stroke-width="2"/>
        <rect x="118" y="88" width="16" height="12" fill="#dc2626" stroke="#7f1d1d" stroke-width="2"/>
        <rect x="138" y="88" width="16" height="12" fill="#dc2626" stroke="#7f1d1d" stroke-width="2"/>
        <!-- Castle Arch Door -->
        <path d="M96 178 V142 A16 16 0 0 1 128 142 V178 Z" fill="#1e1b4b" stroke="#fde047" stroke-width="2"/>
        <text x="112" y="66" text-anchor="middle" font-size="18">🏰</text>
      </g>

      <!-- Playable Teenieping Super Jumper Hero -->
      <g transform="translate(${heroX}, ${heroY}) scale(${heroScale})" class="mario-hero-sprite">
        ${
          state.powerUp === 'star'
            ? `<circle cx="20" cy="20" r="26" fill="none" stroke="#fde047" stroke-width="3" stroke-dasharray="6 4"/>`
            : ''
        }
        <!-- Hero Plumber Cap Visor -->
        <path d="M4 8 Q20 -6 36 8 L42 10 L2 10 Z" fill="#ef4444" stroke="#991b1b" stroke-width="2"/>
        <circle cx="20" cy="4" r="5" fill="#fff"/>
        <!-- Hero Round Body -->
        <circle cx="20" cy="22" r="16" fill="${state.heroAccent}" stroke="#ffffff" stroke-width="2.5"/>
        <text x="20" y="28" text-anchor="middle" font-size="18">${state.heroSymbol}</text>
        <!-- Little Running Boots -->
        <ellipse cx="12" cy="38" rx="7" ry="4" fill="#dc2626" stroke="#fff" stroke-width="1.5"/>
        <ellipse cx="28" cy="38" rx="7" ry="4" fill="#dc2626" stroke="#fff" stroke-width="1.5"/>
      </g>

      <!-- Classic Grass & Brick Ground -->
      <rect x="0" y="178" width="640" height="8" fill="${w.groundTop}"/>
      <rect x="0" y="186" width="640" height="34" fill="url(#m-bricks)"/>
    </svg>`;
  }

  const api = {
    TOTAL_CHECKPOINTS,
    WORLDS,
    OBSTACLE_TYPES,
    createRunState,
    makeBlockQuestion,
    applyJumpResult,
    renderStageSvg,
  };

  api.PlatformerEngine = api;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = api;
  }
  if (typeof root !== 'undefined') {
    root.PlatformerEngine = api;
  }
})(typeof globalThis !== 'undefined' ? globalThis : this);
